[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$RecorderExe,
    [Parameter(Mandatory=$true)][string]$Hoi4Exe,
    [Parameter(Mandatory=$true)][string]$PdxUserDir,
    [Parameter(Mandatory=$true)][string]$CollectorDll,
    [Parameter(Mandatory=$true)][string]$OutDir,
    [Parameter(Mandatory=$true)][string]$ContinueSave,
    [Parameter(Mandatory=$true)][string]$StaticBundleManifest,
    [Parameter(Mandatory=$true)][string]$StaticBundleBindingsDir,
    [string]$PrebuiltArtifactAttestationPath='',
    [string]$ActionProfile='',
    [string]$Python='python',
    [int]$ProcessTimeoutSeconds=420,
    [int]$RecorderDurationSeconds=600,
    [switch]$EnableLegacyClientDriving
)

$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if(-not $EnableLegacyClientDriving){throw 'This legacy owner launches, inputs to, and controls HOI4. It is disabled by default. Use A6_A7_SUPPLY_CONVOY/PASSIVE_OBSERVER_WORKFLOW.json with the shared passive observer; only an explicit -EnableLegacyClientDriving opt-in may enter this quarantined path.'}
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
if([string]::IsNullOrWhiteSpace($ActionProfile)){$ActionProfile=Join-Path $repo 'extractor\re_evidence\A6_A7_SUPPLY_CONVOY\H_CONVOY_AUTONOMOUS_ACTION_PROFILE.json'}
foreach($path in @($RecorderExe,$Hoi4Exe,$PdxUserDir,$CollectorDll,$ContinueSave,$StaticBundleManifest,$StaticBundleBindingsDir,$ActionProfile)){if(-not(Test-Path -LiteralPath $path)){throw "Required H-CONVOY path is absent: $path"}}
$recorder=(Resolve-Path $RecorderExe).Path;$exe=(Resolve-Path $Hoi4Exe).Path;$user=(Resolve-Path $PdxUserDir).Path;$dll=(Resolve-Path $CollectorDll).Path;$save=(Resolve-Path $ContinueSave).Path
$bundle=(Resolve-Path $StaticBundleManifest).Path;$bindings=(Resolve-Path $StaticBundleBindingsDir).Path;$profilePath=(Resolve-Path $ActionProfile).Path;$pythonExe=(Get-Command $Python -CommandType Application).Source
$out=[IO.Path]::GetFullPath($OutDir);$expectedExe='870ebf1f615262facca48a3b947775c41f0a5338f3068c40958209f5c41c65ad';$expectedSave='c8488b05a3b87c718eeff979976537b79e867634d0b4dccb1eef6c5a45362735'
if((Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()-cne$expectedExe){throw 'H-CONVOY requires exact a729 hoi4.exe.'};if((Get-FileHash $save -Algorithm SHA256).Hash.ToLowerInvariant()-cne$expectedSave){throw 'H-CONVOY requires frozen New D04 Save Deep War.'}
if(@(Get-Process the game -ErrorAction SilentlyContinue).Count-ne0){throw 'H-CONVOY requires a clean launch.'};if(Test-Path $out){if(@(Get-ChildItem $out -Force).Count-ne0){throw "OutDir must be absent or empty: $out"}}else{[IO.Directory]::CreateDirectory($out)|Out-Null}
$profile=Get-Content $profilePath -Raw|ConvertFrom-Json;if($profile.schema-cne'hoi4-h-convoy-autonomous-action-profile-v1'-or$profile.authority.save_sha256-cne$expectedSave-or[int]$profile.authority.initial_game_hour_raw-ne60830441-or[int]$profile.authority.client[1]-ne4713-or$profile.policy.no_prompts-ne$true-or$profile.policy.no_console_commands-ne$true){throw 'H-CONVOY action profile authority/policy mismatch.'}
$remote=(Resolve-Path (Join-Path $repo 'extractor\re_evidence\A6_A7_SUPPLY_CONVOY\h_convoy_remote_command.py')).Path;$verify=(Resolve-Path (Join-Path $repo 'extractor\re_evidence\A6_A7_SUPPLY_CONVOY\verify_h_convoy_fixture.py')).Path
$readiness=(Resolve-Path (Join-Path $repo 'replay_interface\re_evidence\rendering_laws\capture_harness\authenticated_wait_for_paused_save.ps1')).Path
$productionDriver=(Resolve-Path (Join-Path $PSScriptRoot 'Start-Hoi4ProductionCaptureSafe.ps1')).Path;$attestationHelpers=(Resolve-Path (Join-Path $PSScriptRoot 'ProductionArtifact.Attestation.ps1')).Path;. $attestationHelpers
if([string]::IsNullOrWhiteSpace($PrebuiltArtifactAttestationPath)){$PrebuiltArtifactAttestationPath=Join-Path $repo '.cargo-target\release\hoi4-production-prebuilt-artifacts.json'}
$prebuilt=Test-ProductionArtifactAttestation -RepoRoot $repo -ReceiptPath $PrebuiltArtifactAttestationPath -ExpectedDriverPath $productionDriver
if(-not[IO.Path]::GetFullPath([string]$prebuilt.artifacts.recorder_host).Equals($recorder,[StringComparison]::OrdinalIgnoreCase)-or-not[IO.Path]::GetFullPath([string]$prebuilt.artifacts.collector_dll).Equals($dll,[StringComparison]::OrdinalIgnoreCase)){throw 'H-CONVOY recorder/collector are not the current central Release artifacts.'}

function Write-Atomic([string]$Path,[string]$Text){$tmp="$Path.$([guid]::NewGuid().ToString('N')).tmp";try{[IO.File]::WriteAllText($tmp,$Text,[Text.UTF8Encoding]::new($false));$s=[IO.File]::Open($tmp,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$s.Flush($true)}finally{$s.Dispose()};if(Test-Path $Path){throw "Refusing to replace immutable output $Path"};[IO.File]::Move($tmp,$Path)}finally{if(Test-Path $tmp){Remove-Item $tmp -Force}}}
if(-not('HConvoyInput' -as[type])){Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;
public static class HConvoyInput { [StructLayout(LayoutKind.Sequential)] public struct I{public uint type;public U u;}[StructLayout(LayoutKind.Explicit)]public struct U{[FieldOffset(0)]public K k;}[StructLayout(LayoutKind.Sequential)]public struct K{public ushort vk,scan;public uint flags,time;public UIntPtr extra;}[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint n,I[] i,int s);public static void Key(IntPtr h,ushort v){if(!SetForegroundWindow(h))throw new Exception("foreground rejected");I d=new I(),u=new I();d.type=u.type=1;d.u.k.vk=v;u.u.k.vk=v;u.u.k.flags=2;if(SendInput(2,new[]{d,u},Marshal.SizeOf(typeof(I)))!=2)throw new Exception("SendInput rejected");}}
'@}
$continuePath=Join-Path $user 'continue_game.json';$priorExists=Test-Path $continuePath -PathType Leaf;$prior=if($priorExists){[IO.File]::ReadAllBytes($continuePath)}else{$null}
$source=if($priorExists){Get-Content $continuePath -Raw|ConvertFrom-Json}else{[pscustomobject]@{title='';desc='';date=[DateTime]::UtcNow.ToString('R');filename='';is_remote=$false}};$source.filename=[IO.Path]::GetFileName($save);$source.is_remote=$false;$replacement=($source|ConvertTo-Json -Depth 8)+"`n"
$bindingNames=@{mod_state='mod_state.json';dlc_state='dlc_state.json';load_order='load_order.json';source_inventory='source_inventory.json';resolution_report='resolution_report.json'};foreach($key in @($bindingNames.Keys)){$bindingNames[$key]=(Resolve-Path (Join-Path $bindings $bindingNames[$key])).Path}

function Invoke-Arm([string]$Arm){
    $armRoot=Join-Path $out $Arm;$native=Join-Path $armRoot 'native';$evidence=Join-Path $armRoot 'evidence';[IO.Directory]::CreateDirectory($native)|Out-Null;[IO.Directory]::CreateDirectory($evidence)|Out-Null
    $nonce=[guid]::NewGuid().ToString('N');$session=[guid]::NewGuid().ToString();$capture=[guid]::NewGuid().ToString();$manifest=Join-Path $native 'native_session_manifest.json';$ready=Join-Path $armRoot 'paused_save_readiness.json';$steps=[Collections.Generic.List[object]]::new();$ownedStart=$null
    [IO.File]::WriteAllText($continuePath,$replacement,[Text.UTF8Encoding]::new($false))
    $args=@('--early-launch-exe',$exe,'--early-launch-arg','--continuelastsave','--early-launch-arg','--gdpr-compliant','--pdx-user-dir',$user,'--dll',$dll,'--out-dir',$native,'--session-id',$session,'--capture-id',$capture,'--duration-s',$RecorderDurationSeconds,'--sample-ms','25','--stream-format','compact','--profile','debug','--sidecar-log','--hour-latch','--static-bundle-manifest',$bundle,'--static-bundle-mod-state',$bindingNames.mod_state,'--static-bundle-dlc-state',$bindingNames.dlc_state,'--static-bundle-load-order',$bindingNames.load_order,'--static-bundle-source-inventory',$bindingNames.source_inventory,'--static-bundle-live-resolution-report',$bindingNames.resolution_report,'--static-bundle-verifier',(Join-Path $repo 'extractor\game_defs\static_bundle.py'),'--static-bundle-python',$pythonExe,'--static-bundle-timeout-ms','300000')
    $job=Start-Job -ScriptBlock {param($e,$a,$n);$env:BATTLE_PLAN_ENABLE_H_CONVOY_EVIDENCE_HOOK='1';$env:BATTLE_PLAN_H_CONVOY_SESSION_NONCE=$n;& $e @a;if($LASTEXITCODE-ne0){throw "collector exited $LASTEXITCODE"}} -ArgumentList $recorder,(,$args),$nonce;$game=$null
    try{$deadline=[DateTime]::UtcNow.AddSeconds($ProcessTimeoutSeconds);while([DateTime]::UtcNow-lt$deadline-and$null-eq$game){$c=@(Get-Process the game -ErrorAction SilentlyContinue);if($c.Count-gt1){throw 'Multiple the game processes appeared.'};foreach($p in $c){try{$mods=@($p.Modules|Where-Object{[IO.Path]::GetFullPath($_.FileName).Equals($dll,[StringComparison]::OrdinalIgnoreCase)});if($p.MainWindowHandle-ne[IntPtr]::Zero-and$mods.Count-eq1-and(Get-FileHash $p.MainModule.FileName -Algorithm SHA256).Hash.ToLowerInvariant()-ceq$expectedExe){$game=$p}}catch{}};if($null-eq$game){Start-Sleep -Milliseconds 250}};if($null-eq$game){throw "H-CONVOY $Arm process readiness timed out."}
        $ownedStart=$game.StartTime.ToUniversalTime().ToString('o');& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $readiness -ProcessId $game.Id -ReceiptPath $ready -ExpectedGameHourRaw 60830441 -TimeoutSeconds $ProcessTimeoutSeconds -StableSamples 4 -PollMilliseconds 250;if($LASTEXITCODE-ne0){throw "H-CONVOY $Arm paused-save authentication failed."}
        $install=@{operation='install';output_root=$evidence;arm=$Arm;session_nonce=$nonce;client_id=[int]$profile.authority.client[0];client_type_tag=[int]$profile.authority.client[1];utc_start=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress
        & $pythonExe $remote --process-id $game.Id --collector-dll $dll --command-json $install;if($LASTEXITCODE-ne0){throw "H-CONVOY $Arm hook installation failed."}
        foreach($action in $profile.$Arm.actions){$started=[DateTime]::UtcNow.ToString('o');if($action.kind-ceq'send_input_key'){[HConvoyInput]::Key($game.MainWindowHandle,[ushort]$action.virtual_key)}elseif($action.kind-ceq'wait'){Start-Sleep -Milliseconds ([int]$action.milliseconds)}else{throw "Unsupported H-CONVOY action $($action.kind)"};$steps.Add([ordered]@{label=[string]$action.label;kind=[string]$action.kind;virtual_key=if($action.PSObject.Properties['virtual_key']){[int]$action.virtual_key}else{$null};milliseconds=if($action.PSObject.Properties['milliseconds']){[int]$action.milliseconds}else{$null};started_utc=$started;completed_utc=[DateTime]::UtcNow.ToString('o');input_api=if($action.kind-ceq'send_input_key'){'user32!SendInput'}else{$null}})}
        $seal=@{operation='seal';utc_end=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress;& $pythonExe $remote --process-id $game.Id --collector-dll $dll --command-json $seal;if($LASTEXITCODE-ne0){throw "H-CONVOY $Arm seal failed."}
    }finally{if($null-ne$game-and$null-ne(Get-Process -Id $game.Id -ErrorAction SilentlyContinue)){Stop-Process -Id $game.Id -Force};if($null-ne$job){Wait-Job $job -Timeout 30|Out-Null;if($job.State-notin@('Completed','Failed')){Stop-Job $job};Receive-Job $job -ErrorAction SilentlyContinue|Out-Null;Remove-Job $job -Force}}
    if(-not(Test-Path (Join-Path $evidence 'arm_acquisition.json'))){throw "H-CONVOY $Arm arm receipt is absent."};$actionPath=Join-Path $armRoot 'action_receipt.json';Write-Atomic $actionPath (([ordered]@{schema='h-convoy-autonomous-action-receipt-v1';arm=$Arm;session_nonce=$nonce;process_id=$game.Id;process_start_utc=$ownedStart;executable_sha256=$expectedExe;save_sha256=$expectedSave;steps=$steps;no_prompts=$true;no_console_commands=$true}|ConvertTo-Json -Depth 12)+"`n");$result=Get-Content (Join-Path $evidence 'arm_acquisition.json') -Raw|ConvertFrom-Json;$result|Add-Member -NotePropertyName owner_action_receipt -NotePropertyValue ([pscustomobject]@{path="$Arm/action_receipt.json";sha256=(Get-FileHash $actionPath -Algorithm SHA256).Hash.ToLowerInvariant()}) -Force;return $result
}

try{$positive=Invoke-Arm 'positive';$negative=Invoke-Arm 'negative'}finally{if($priorExists){[IO.File]::WriteAllBytes($continuePath,$prior)}elseif(Test-Path $continuePath){Remove-Item $continuePath -Force}}
function Prefix-Arm($arm,[string]$name){foreach($f in $arm.raw_files){$f.path="$name/evidence/$($f.path)"};foreach($f in $arm.cta2_batches){$f.path="$name/evidence/$($f.path)"};$arm|Add-Member -NotePropertyName baseline_save -NotePropertyValue ([pscustomobject]@{path=$save;sha256=$expectedSave;game_hour_raw=60830441}) -Force;return $arm}
$positive=Prefix-Arm $positive 'positive';$negative=Prefix-Arm $negative 'negative'
if([int]$negative.route_start.client[0]-ne[int]$profile.authority.client[0]-or[int]$negative.route_start.client[1]-ne[int]$profile.authority.client[1]-or[int]$negative.route_start.producer_kind-ne[int]$profile.authority.route.producer_kind-or[int]$negative.route_start.source_id-ne[int]$profile.authority.route.source_id-or[int]$negative.route_start.destination_id-ne[int]$profile.authority.route.destination_id){throw 'H-CONVOY live negative route differs from the frozen action profile.'}
$pair=[ordered]@{schema='h-convoy-control-pair-v1';binary=[ordered]@{sha256=$expectedExe;image_base='0x140000000'};static_authority_manifest_sha256='42cfb445b2eb539f40b9525392df129c0d72c2e328219cbf8d8e75f6d6c5614d';route_source_authority=[ordered]@{job_id='20260720T064512Z-w4-h-convoy-reference-key-order-final-81329482';job_json_sha256='d250fba6a57797d62f71043a26f64a683f43a76a3932d9446835b488aa95485b';semantic_request_sha256='8e82ffc4ef2ff943caf237fb9ac0a75df19699f9af912f015df148c5da9ddd6a';artifact_manifest_sha256='13ba6fc30850be81559f49cdab3569fde866ce06ec29789ffb5307874b09df31';resolver_decompile_sha256='6ded7904dfb3b892721972f2a53adcdb72ddac8d9d8f85af94764903a3023fef';lookup_decompile_sha256='86f8ae2455f65c246487ed38d02ce6af8163be9ec882b45a8279c31fc740944b'};callsite_context_hex='4d8d4c24204d8bc7ba01000000488b0d184b9b01e8138b86fe';hook_rva='0x1962378';target_rva='0x1CAE90';positive=$positive;negative=$negative}
$manifestPath=Join-Path $out 'h_convoy_control_pair.json';Write-Atomic $manifestPath (($pair|ConvertTo-Json -Depth 30)+"`n")
$grade1=Join-Path $out 'h_convoy_regrade_primary.json';$grade2=Join-Path $out 'h_convoy_regrade_independent.json';& $pythonExe $verify $manifestPath --out $grade1;if($LASTEXITCODE-ne0){throw 'H-CONVOY primary regrade rejected the pair.'};& $pythonExe $verify $manifestPath --out $grade2;if($LASTEXITCODE-ne0){throw 'H-CONVOY independent regrade rejected the pair.'}
$g1=Get-Content $grade1 -Raw|ConvertFrom-Json;$g2=Get-Content $grade2 -Raw|ConvertFrom-Json;if($g1.production_admission-ne$true-or$g2.production_admission-ne$true-or$g1.control_pair_sha256-cne$g2.control_pair_sha256){throw 'H-CONVOY independent regrades disagree.'}
$receipt=[ordered]@{schema='h-convoy-autonomous-acquisition-receipt-v1';status='PASS';control_pair_sha256=$g1.control_pair_sha256;manifest_sha256=(Get-FileHash $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant();primary_regrade_sha256=(Get-FileHash $grade1 -Algorithm SHA256).Hash.ToLowerInvariant();independent_regrade_sha256=(Get-FileHash $grade2 -Algorithm SHA256).Hash.ToLowerInvariant();verifier_sha256=(Get-FileHash $verify -Algorithm SHA256).Hash.ToLowerInvariant();action_profile_sha256=(Get-FileHash $profilePath -Algorithm SHA256).Hash.ToLowerInvariant();prebuilt_attestation_sha256=(Get-FileHash ([string]$prebuilt.receipt_path) -Algorithm SHA256).Hash.ToLowerInvariant();production_domain_90_scheduled=$false;production_activation_changed=$false}
$receiptPath=Join-Path $out 'h_convoy_autonomous_acquisition_receipt.json';Write-Atomic $receiptPath (($receipt|ConvertTo-Json -Depth 8)+"`n");Write-Output "H-CONVOY branched pair admitted: $receiptPath"
